"""Cross-phase correction discovery.

A *correction* is the user revising a value they already provided earlier in
the conversation ("I meant the Freedom card", "it's damaged, not stolen",
"make it rush") while the conversation has already moved to a later phase.

This module owns the **variant-agnostic** discovery half of the mechanism:
:func:`find_correctable_fields` computes, per turn, which memory items are
eligible to be corrected. Discovery is **write-driven**: it scans the
memory-write history (``MemorySet``, ``MemoryCleared``, or ``SlotSet``) and
uses each key's latest write-provenance to find the
producing frame, regardless of variant (a guided collect and an autonomous tool
both stamp provenance). This covers values produced by a frame **currently on
the stack** *and* values produced by a sub-skill that has since completed and
popped but ran under an ancestor still on the stack (cross-skill correction,
surfaced with ``requires_reentry``). The memory item being asked right now is
excluded.

The replay drivers live in :mod:`.replay` and :mod:`.executor`; this module is
import-light so both the tool-schema builder and the dispatcher can depend on it.
"""

from __future__ import annotations

import os
from typing import TYPE_CHECKING, Dict, List, Optional

import structlog

from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.memory.field import MemoryField
from rasa.mantle.memory.manager import PROJECT_NAMESPACE
from rasa.mantle.orchestration.correction.models import CorrectableMemoryItem
from rasa.mantle.skills.catalog import resolved_memory_field_description
from rasa.mantle.skills.stack_frame_helpers import SYNTHETIC_PROSE_STEP_ID
from rasa.mantle.skills.steps import AutonomousStep, CollectStep
from rasa.mantle.state.provenance import (
    WriteProvenance,
    iter_slot_writes,
    provenance_for_slot_by_frame,
)

if TYPE_CHECKING:
    from rasa.dialogue_understanding.stack.dialogue_stack import DialogueStack
    from rasa.mantle.memory.manager import MemoryManager
    from rasa.mantle.skills.catalog import ResolvedActivationTarget, SkillCatalog
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()

# Escape hatch (also the feature's documented backout): when this env var is
# truthy the engine discovers no correctable values, so no ``correct`` tool is
# offered, no correction reminder is added to the prompt, and any stray
# ``correct`` call is rejected — reverting to pre-feature behavior. Used to
# measure the correction feature's lift against an otherwise identical tree
# (same trained model, harness, example bots, and scenarios) in evaluation.
_DISABLE_CORRECTION_ENV = "RASA_MANTLE_DISABLE_CORRECTION"


def correction_disabled() -> bool:
    """Return ``True`` when cross-phase correction is disabled via env var."""
    return os.environ.get(_DISABLE_CORRECTION_ENV, "").strip().lower() not in (
        "",
        "0",
        "false",
        "no",
    )


def _active_collect_key(
    tracker_handle: "TrackerHandle", active_collect_step: Optional["CollectStep"]
) -> Optional[str]:
    """Return the memory key (slot name) the agent is asking for now, or ``None``.

    This resolves the active collect step's entry to its fully-qualified tracker
    slot name (memory key), so the caller can compare it against the keys in the
    write history. Correcting the value the agent is *currently* asking for is a
    normal answer, not a correction, so its key is excluded from the correctable
    set. The active collect step is resolved by the executor (which already
    exposes :meth:`SkillExecutor.active_collect_step`) and passed in, so this
    module does not re-derive it.
    """
    if active_collect_step is None:
        return None
    frame = tracker_handle.active_frame
    if frame is None:
        return None
    skill_id, flow_id = tracker_handle.memory.resolve_scope(frame)
    try:
        return tracker_handle.memory.resolve(
            skill_id, flow_id, active_collect_step.collect
        )
    except ValueError:
        return None


def is_autonomous_skill(
    target: "ResolvedActivationTarget", skill_catalog: "SkillCatalog"
) -> bool:
    """Return ``True`` when *target* is an autonomous skill's sole entry.

    The sole entry may be prose or an ordered block. It has no deterministic steps
    to rewind through, so the replay driver hands a correction back to the LLM
    instead of repositioning the stack.

    A prose entry inside a *hybrid* skill (a skill that also owns ordered blocks
    the autonomous step can link into) is **not** autonomous for replay purposes:
    its corrections may target deterministic steps, so this returns ``False``
    when the owning skill has more than one activation target.
    """
    if not (len(target.steps) == 1 and isinstance(target.steps[0], AutonomousStep)):
        return False
    skill = skill_catalog.owning_skill_for_target_id(target.target_id)
    if skill is None:
        return False
    from rasa.mantle.skills.catalog import iter_resolved_activation_targets

    return len(iter_resolved_activation_targets(skill)) == 1


def find_correctable_fields(
    tracker_handle: "TrackerHandle",
    skill_catalog: "SkillCatalog",
    active_collect_step: Optional["CollectStep"] = None,
    excluded_memory_key: Optional[str] = None,
) -> List[CorrectableMemoryItem]:
    """Return the memory items eligible for correction on the current turn.

    Discovery is **write-driven** and variant-agnostic: it scans memory-write
    events (``MemorySet``, ``MemoryCleared``, or ``SlotSet``) and, for each
    key, uses its *latest* write-provenance to find the producing stack frame.
    A slot is correctable when:

    * its latest value is still set (a cleared slot has nothing to correct);
    * the frame that produced it is **currently on the stack** (a guided collect
      and an autonomous tool both stamp the producing ``frame_id``), **or** it
      was produced by a sub-skill that has since completed and popped but ran
      under an ancestor still on the stack — surfaced with ``requires_reentry``
      so the replay driver reconstructs the stack from history to re-enter it
      (cross-skill correction);
    * it is readable from the producing frame's skill; and
    * it is **not** the field the agent is asking for right now; and
    * it is **not** ``excluded_memory_key``. A button tap passes the key it
      just wrote so that value is not offered to ``correct`` on the same turn.

    A ``project.*`` slot is never offered: the LLM cannot ``correct`` project
    memory, and those values stay set for the rest of the session.

    A write is offered for correction only when it represents a **user-provided
    memory item** (see :func:`_is_user_provided`): either a value a ``collect``
    step owns (the engine asked the user directly) or a value whose field
    declares :attr:`~rasa.mantle.memory.field.MemoryField.llm_settable` (a user
    decision recorded via a tool in an autonomous/instruction step). Engine-derived
    writes — eligibility, lock state, computed flags — leave the flag ``False`` and
    are skipped as scratch state, not decisions.

    The rewind target is the **owning collect step** where one declares the field
    (found from the flow graph), not where the value happened to be written (it
    can be re-produced by a tool at a later step). When no collect step owns the
    slot it falls back to the frame's current step — which for a single autonomous
    skill is the ``AutonomousStep`` (replay hands the value back to the LLM), and
    for a hybrid flow that wraps an ``AutonomousStep`` is that autonomous step
    (also a valid rewind target, since autonomous steps set user-facing memory
    items too). Slots appear in first-write order, giving a stable enum order.

    Returns an empty list when correction is disabled via
    :data:`_DISABLE_CORRECTION_ENV` (see :func:`correction_disabled`).
    """
    if correction_disabled():
        return []
    active_collect_key = _active_collect_key(tracker_handle, active_collect_step)
    frames_by_id = {
        frame.frame_id: frame
        for frame in (
            *tracker_handle.skill_and_block_frames(),
            *tracker_handle.user_flow_frames(),
        )
    }
    current_frame_ids = set(frames_by_id)

    latest_writes, writing_frames = _scan_slot_writes(tracker_handle)

    # Only replay history to find completed sub-skills when some write was
    # produced by a frame no longer on the stack — otherwise the common case
    # (no completed sub-skills) pays no replay cost.
    off_stack_writer = any(
        frame_id not in current_frame_ids
        for frame_ids in writing_frames.values()
        for frame_id in frame_ids
    )
    subskill_snaps: Dict[str, "DialogueStack"] = (
        _completed_subskill_snapshots(tracker_handle, current_frame_ids)
        if off_stack_writer
        else {}
    )
    subskill_frame_ids = set(subskill_snaps)

    results: List[CorrectableMemoryItem] = []
    project_prefix = f"{PROJECT_NAMESPACE}."
    for slot_name, provenance in latest_writes.items():
        if slot_name.startswith(project_prefix):
            continue
        if (
            slot_name == active_collect_key
            or slot_name == excluded_memory_key
            or provenance is None
        ):
            continue
        frame = frames_by_id.get(provenance.frame_id or "")
        if frame is None:
            # Produced by a frame no longer on the stack. If it was a sub-skill
            # that ran under an ancestor still on the stack, it can be corrected
            # by re-entering that sub-skill (cross-skill path); otherwise skip.
            reentry = _reentry_correctable_field(
                tracker_handle, skill_catalog, subskill_snaps, slot_name, provenance
            )
            if reentry is not None:
                results.append(reentry)
            continue
        # On-stack latest write, but the value was *originally* produced by a
        # completed sub-skill (an ancestor later re-stamped it — e.g. an
        # eligibility recompute re-writing the chosen card id). The user-facing
        # decision belongs to the sub-skill, not the ancestor: correcting the
        # ancestor's derived copy in place cannot re-select the card. So surface
        # the sub-skill's own value via re-entry (anchored on the sub-skill's
        # original write) instead of the on-stack ancestor handle — a single,
        # working handle (owner-scoped rule). The latest write being on-stack
        # means the `frame is None` re-entry branch above never fires for it, so
        # we resolve re-entry here from the originating sub-skill frame.
        originating_subskill_ids = (
            writing_frames.get(slot_name) or set()
        ) & subskill_frame_ids
        if originating_subskill_ids:
            reentry = _restamped_reentry_correctable_field(
                tracker_handle,
                skill_catalog,
                subskill_snaps,
                slot_name,
                originating_subskill_ids,
            )
            if reentry is not None:
                results.append(reentry)
            continue
        onstack = _onstack_correctable_field(
            tracker_handle, skill_catalog, frame, slot_name, provenance
        )
        if onstack is not None:
            results.append(onstack)
    return results


def _onstack_correctable_field(
    tracker_handle: "TrackerHandle",
    skill_catalog: "SkillCatalog",
    frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    slot_name: str,
    provenance: WriteProvenance,
) -> Optional[CorrectableMemoryItem]:
    """Build a correctable item for a value produced by a frame on the stack.

    Returns ``None`` unless the value is still set, readable from the producing
    frame's skill, not a derived ``json`` record, and **user-provided**
    (see :func:`_is_user_provided`) with an applicable producer. The rewind target
    is the owning collect step, falling back to the frame's current step (the
    autonomous step for autonomous / hybrid flows).
    """
    value = tracker_handle.get_slot(slot_name)
    if value is None:
        return None
    memory = tracker_handle.memory
    item = memory.reverse_lookup(slot_name)
    if item is None:
        # Reserved system.* namespace — not user-correctable.
        return None
    if item.field.type == "json":
        # A json memory item holds derived/structured records (e.g. fetched
        # transactions), not a user decision. Offering it for correction bloats
        # the prompt and risks leaking its contents into the tool description, so
        # it is never surfaced.
        return None
    frame_skill_id, flow_id = memory.resolve_scope(frame)
    if memory.get(frame_skill_id, flow_id, slot_name) is None:
        # Read denied from the producing frame's skill.
        return None
    skill_id = item.skill_id or frame_skill_id
    target = skill_catalog.resolve_activation_target(flow_id)
    collect_step = _owning_collect_step_id(target, memory, skill_id, flow_id, slot_name)
    if not _is_user_provided(collect_step, item.field):
        # Only user-provided values are offered for correction: one a collect step
        # owns (the engine asked the user) or a memory item the schema declares
        # ``llm_settable`` (a user decision recorded via a tool). Engine-derived
        # values (eligibility, lock state, computed flags) are scratch/derived
        # state, not user decisions — skip them.
        return None
    if (
        collect_step is None
        and not provenance.produced_by_tool
        and not item.field.llm_settable
    ):
        # Engine-derived values with no collect step, no tool producer, and not
        # ``llm_settable`` have no correction path — skip them.
        return None
    return CorrectableMemoryItem(
        memory_key=slot_name,
        entry_name=item.entry_name,
        skill_id=skill_id,
        flow_id=flow_id,
        frame_id=frame.frame_id,
        step_id=collect_step or _fallback_step_id(frame, target),
        field=item.field,
        resolved_description=_resolved_description_for_entry(
            skill_catalog, skill_id, item.entry_name
        ),
        current_value=value,
    )


def _resolved_description_for_entry(
    skill_catalog: SkillCatalog, skill_id: str, entry_name: str
) -> str | None:
    """Return the description the model sees for one correctable entry."""
    skill = skill_catalog.skill_by_id(skill_id)
    if skill is None:
        return None
    return resolved_memory_field_description(skill, entry_name)


def _is_user_provided(collect_step: Optional[str], field: MemoryField) -> bool:
    """Return ``True`` when a memory item is a user-provided (correctable) value.

    A value is user-provided when a ``collect`` step owns it (the engine asked
    the user directly, so no schema flag is needed) or when the schema declares
    the field ``llm_settable`` (a user decision recorded via a tool in an
    autonomous/instruction step). Engine-derived values — eligibility, lock
    state, computed flags — satisfy neither and are never offered for correction.
    """
    return collect_step is not None or field.llm_settable


def _fallback_step_id(
    frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    target: Optional["ResolvedActivationTarget"],
) -> str:
    """Return the rewind step when no collect step owns the field.

    Ordered-block and user-flow frames keep their persisted ``step_id``.
    Skill frames have none; use the catalog's autonomous step when present.
    """
    if isinstance(frame, SkillStackFrame):
        if target is not None:
            for step in target.steps:
                if isinstance(step, AutonomousStep):
                    return step.id
        return SYNTHETIC_PROSE_STEP_ID
    return frame.step_id


def _owning_collect_step_id(
    target: Optional["ResolvedActivationTarget"],
    memory: "MemoryManager",
    skill_id: str,
    flow_id: str,
    slot_name: str,
) -> Optional[str]:
    """Return the id of the collect step that declares *slot_name*, if any.

    The rewind target is the step that *owns* a field (declares the ``collect``),
    which is where replay must re-ask it — distinct from wherever the value was
    last written (it may have been re-produced by a tool at a later step). Returns
    ``None`` when no collect step owns the slot (e.g. autonomous flows or
    tool-only values), leaving the caller to fall back to the frame's step.
    """
    if target is None:
        return None
    for step in target.steps:
        if not isinstance(step, CollectStep):
            continue
        try:
            if memory.resolve(skill_id, flow_id, step.collect) == slot_name:
                return step.id
        except ValueError:
            continue
    return None


def _reentry_target_step(
    target: Optional["ResolvedActivationTarget"],
    collect_step: Optional[str],
    *,
    llm_settable: bool = False,
) -> Optional[str]:
    """Return the step to re-enter a completed sub-skill at, or ``None``.

    A collect step that owns the value is the precise re-ask target (a guided
    sub-skill). Failing that, an ``llm_settable`` value (written directly by the
    engine) is re-entered at the sub-skill's
    :class:`~rasa.mantle.skills.steps.AutonomousStep`: the corrected value is
    applied first, so re-walking the step lets the LLM re-derive the remaining
    state and the sub-skill completes, handing control back to the ancestor.
    This covers both a pure autonomous skill (a single ``AutonomousStep``) and a
    hybrid view that wraps an ``AutonomousStep`` with an ``END`` sentinel.

    Callers only reach here for user-provided values (collect-owned or
    ``llm_settable``), so an ``llm_settable`` value with no owning collect step
    always has ``llm_settable=True``; no separate tool-producer check is needed.
    """
    if collect_step is not None:
        return collect_step
    if target is not None and llm_settable:
        for step in target.steps:
            if isinstance(step, AutonomousStep):
                return step.id
    return None


def _completed_subskill_snapshots(
    tracker_handle: "TrackerHandle", current_frame_ids: set[str]
) -> Dict[str, "DialogueStack"]:
    """Map each completed sub-skill ``frame_id`` to its latest historical stack.

    A frame qualifies when, in some past stack state, it was the **top** frame
    (so it was the active sub-skill), it is **no longer** on the current stack
    (it completed and popped), and at least one frame **below** it in that
    snapshot is still on the current stack (a live ancestor to return to). Those
    are exactly the values a cross-phase correction can re-enter.

    Reconstruction is a **single pass** over the stack-changing events only:
    ``DialogueStackUpdated`` patches (from :meth:`applied_events`) are replayed
    onto one running :class:`DialogueStack`, and the latest state in which each
    frame was the top is kept. This is the hot per-turn path (discovery runs
    every turn), so it deliberately avoids
    :meth:`DialogueStateTracker.previous_stack_states`, which replays *every*
    applied event through a full tracker copy and deep-copies the stack on each
    change — O(events) with heavy constants, growing O(n^2) over a conversation.
    Because a frame's ancestors are fixed for its lifetime on the stack (LIFO:
    the frames below it cannot pop while it sits above them), keeping only the
    latest top-state per frame yields the same qualifying set as scanning every
    historical snapshot.

    The event log is read defensively (missing accessor, or a malformed patch)
    so handles wrapping minimal test trackers, or a corrupt persisted stack,
    yield an empty map rather than raising — the turn degrades to no re-entry
    discovery instead of crashing.
    """
    from rasa.dialogue_understanding.stack.dialogue_stack import DialogueStack
    from rasa.shared.core.events import DialogueStackUpdated

    applied_events = getattr(tracker_handle.tracker, "applied_events", None)
    if applied_events is None:
        return {}

    latest_top_stack: Dict[str, "DialogueStack"] = {}
    try:
        stack = DialogueStack.empty()
        for event in applied_events():
            if not isinstance(event, DialogueStackUpdated):
                continue
            stack = stack.update_from_patch(event.update)
            frames = stack.frames
            if not frames:
                continue
            top_frame_id = getattr(frames[-1], "frame_id", None)
            if top_frame_id is not None:
                latest_top_stack[top_frame_id] = stack
    except Exception:
        structlogger.warning(
            "mantle.correction.subskill_snapshots_failed",
            exc_info=True,
        )
        return {}

    snapshots: Dict[str, "DialogueStack"] = {}
    for top_frame_id, snapshot in latest_top_stack.items():
        if top_frame_id in current_frame_ids:
            continue
        ancestor_ids = {
            getattr(frame, "frame_id", None) for frame in snapshot.frames[:-1]
        }
        if ancestor_ids & current_frame_ids:
            snapshots[top_frame_id] = snapshot
    return snapshots


def _reentry_correctable_field(
    tracker_handle: "TrackerHandle",
    skill_catalog: "SkillCatalog",
    subskill_snaps: Dict[str, "DialogueStack"],
    slot_name: str,
    provenance: WriteProvenance,
) -> Optional[CorrectableMemoryItem]:
    """Build a ``requires_reentry`` item for a completed sub-skill's value.

    Returns ``None`` unless the value was produced by a qualifying completed
    sub-skill (see :func:`_completed_subskill_snapshots`), is still set, readable
    from the historical frame's skill, and **user-provided** — i.e. either
    owned by a collect step of that sub-skill (the well-defined step to re-ask on
    re-entry) or a tool-produced value the schema declares ``llm_settable`` in an
    autonomous sub-skill (re-entered at its autonomous step via
    :func:`_reentry_target_step`). Tool-produced values the schema does *not*
    flag are engine-derived scratch state and remain out of scope.
    """
    snapshot = subskill_snaps.get(provenance.frame_id or "")
    if snapshot is None:
        return None
    hist_frame = snapshot.frames[-1]
    if not isinstance(
        hist_frame, (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame)
    ):
        return None
    value = tracker_handle.get_slot(slot_name)
    if value is None:
        return None
    memory = tracker_handle.memory
    item = memory.reverse_lookup(slot_name)
    if item is None:
        return None
    if item.field.type == "json":
        # Derived/structured records are not user decisions — never surfaced
        # for correction (mirrors the on-stack discovery rule).
        return None
    frame_skill_id, flow_id = memory.resolve_scope(hist_frame)
    if memory.get(frame_skill_id, flow_id, slot_name) is None:
        return None
    skill_id = item.skill_id or frame_skill_id
    target = skill_catalog.resolve_activation_target(flow_id)
    collect_step = _owning_collect_step_id(target, memory, skill_id, flow_id, slot_name)
    if not _is_user_provided(collect_step, item.field):
        # Only user-provided values (collect-owned or schema-declared
        # ``llm_settable``) are re-entry correctable. A tool-produced value the
        # schema does not flag is engine-derived scratch state — skip it.
        return None
    reentry_step = _reentry_target_step(
        target, collect_step, llm_settable=item.field.llm_settable
    )
    if reentry_step is None:
        return None
    structlogger.debug(
        "mantle.correction.reentry_field_surfaced",
        slot_name=slot_name,
        frame_id=provenance.frame_id,
        skill_id=skill_id,
        step_id=reentry_step,
        autonomous=collect_step is None,
    )
    return CorrectableMemoryItem(
        memory_key=slot_name,
        entry_name=item.entry_name,
        skill_id=skill_id,
        flow_id=flow_id,
        frame_id=provenance.frame_id or "",
        step_id=reentry_step,
        field=item.field,
        resolved_description=_resolved_description_for_entry(
            skill_catalog, skill_id, item.entry_name
        ),
        current_value=value,
        requires_reentry=True,
    )


def _restamped_reentry_correctable_field(
    tracker_handle: "TrackerHandle",
    skill_catalog: "SkillCatalog",
    subskill_snaps: Dict[str, "DialogueStack"],
    slot_name: str,
    originating_subskill_ids: set[str],
) -> Optional[CorrectableMemoryItem]:
    """Surface a re-entry handle for a sub-skill value re-stamped by an ancestor.

    Handles the case where a completed sub-skill produced *slot_name* and a
    still-live ancestor later re-wrote the same slot, so its *latest* provenance
    points at the on-stack ancestor and the ``frame is None`` re-entry branch in
    :func:`find_correctable_fields` never sees it. We rebuild the re-entry handle
    from the sub-skill's **own** original write (:func:`provenance_for_slot_by_frame`)
    so the correction anchors on and re-invokes the sub-skill's producer, not the
    ancestor's derived copy. Returns the first qualifying handle, or ``None``.
    """
    for frame_id in sorted(originating_subskill_ids):
        provenance = provenance_for_slot_by_frame(
            tracker_handle.tracker.events, slot_name, frame_id
        )
        if provenance is None:
            continue
        reentry = _reentry_correctable_field(
            tracker_handle, skill_catalog, subskill_snaps, slot_name, provenance
        )
        if reentry is not None:
            return reentry
    return None


def _scan_slot_writes(
    tracker_handle: "TrackerHandle",
) -> tuple[Dict[str, Optional[WriteProvenance]], Dict[str, set[str]]]:
    """Walk memory-write history once and return both views discovery needs.

    Returns a ``(latest_writes, writing_frames)`` pair from a single pass over
    the event log (discovery runs every turn, so a long conversation should not
    pay two full scans):

    - ``latest_writes`` maps each slot to its *latest* write-provenance, keyed in
      first-write order so the correction enum has a stable ordering. Provenance
      is ``None`` for an engine-internal write with no stamped context.
    - ``writing_frames`` maps each slot to the set of *every* frame id that wrote
      it, so discovery can tell that a value re-stamped by an ancestor was
      originally produced by a (now completed) sub-skill.

    The event log is read defensively so handles wrapping minimal test trackers
    (without an ``events`` log) yield empty maps rather than raising.
    """
    latest: Dict[str, Optional[WriteProvenance]] = {}
    order: List[str] = []
    frame_ids: Dict[str, set[str]] = {}
    events = getattr(tracker_handle.tracker, "events", ()) or ()
    for event, provenance in iter_slot_writes(events):
        if event.key not in latest:
            order.append(event.key)
        latest[event.key] = provenance
        if provenance is not None and provenance.frame_id:
            frame_ids.setdefault(event.key, set()).add(provenance.frame_id)
    ordered_latest = {key: latest[key] for key in order}
    return ordered_latest, frame_ids
